const woman2=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><ellipse cx="0" cy="196" rx="100" ry="14" fill="#000" opacity=".14"/><path d="M-92 196 Q-96 74 0 70 Q96 74 92 196Z" fill="#7c3aed"/><path d="M-60 80 Q0 150 60 80" fill="none" stroke="#ddd6fe" stroke-width="14"/><rect x="-18" y="40" width="36" height="40" fill="#a8714a"/><circle cx="0" cy="0" r="58" fill="#a8714a"/><path d="M-64 6 Q-70 -70 0 -66 Q70 -70 64 6 Q50 -30 0 -36 Q-50 -30 -64 6Z" fill="#1c1917"/><path d="M-64 6 Q-80 90 -50 120" stroke="#1c1917" stroke-width="22" fill="none"/><circle cx="-20" cy="6" r="6" fill="#1c1917"/><circle cx="20" cy="6" r="6" fill="#1c1917"/><path d="M-16 28 Q0 40 16 28" stroke="#7c2d12" stroke-width="5" fill="none"/></g>`;
// broker: head centre at (x,y)
const brk=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><ellipse cx="0" cy="196" rx="100" ry="14" fill="#000" opacity=".14"/><path d="M-92 196 Q-96 74 0 70 Q96 74 92 196Z" fill="#3f3f46"/><path d="M-20 74 L0 150 L20 74Z" fill="#fef3c7"/><path d="M-8 84 L0 140 L8 84Z" fill="#b91c1c"/><rect x="-18" y="40" width="36" height="40" fill="#c99470"/><circle cx="0" cy="0" r="58" fill="#c99470"/><path d="M-62 -14 Q-60 -66 0 -66 Q60 -66 62 -14Z" fill="#27272a"/><rect x="-70" y="-22" width="140" height="14" rx="7" fill="#27272a"/><rect x="-44" y="-4" width="38" height="22" rx="8" fill="#111"/><rect x="6" y="-4" width="38" height="22" rx="8" fill="#111"/><rect x="-6" y="2" width="12" height="5" fill="#111"/><path d="M-18 34 Q4 44 22 30" stroke="#7c2d12" stroke-width="5" fill="none"/></g>`;
const cloudS=(x,y,s=1,col='#fff')=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-150 60 Q-210 60 -205 5 Q-200 -45 -140 -40 Q-130 -110 -50 -110 Q20 -150 70 -80 Q150 -100 165 -20 Q220 -10 210 40 Q205 75 160 75 H-150Z" fill="${col}" stroke="${C.b}" stroke-width="8"/></g>`;
const scanner=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="-150" y="-30" width="300" height="110" rx="20" fill="#334155"/><rect x="-150" y="-60" width="300" height="40" rx="14" fill="#64748b"/><rect x="-120" y="20" width="240" height="10" rx="5" fill="#22c55e"/><circle cx="110" cy="55" r="10" fill="#22c55e"/></g>`;
const pdfF=(x,y,l,col=C.r,w=230)=>`<g>${card(x,y,w,70,'#fff',16)}<rect x="${x}" y="${y}" width="62" height="70" rx="16" fill="${col}"/>${lat(x+31,y+44,'PDF',20,'#fff',800)}${lat(x+76,y+44,l,l.length>14?18:22,C.ink,800,'start')}</g>`;
const octo=(x,y,r,col=C.r)=>{let d='';for(let i=0;i<8;i++){const a=Math.PI/8+i*Math.PI/4;d+=(i?'L':'M')+(x+Math.cos(a)*r).toFixed(1)+' '+(y+Math.sin(a)*r).toFixed(1)}return `<path d="${d}Z" fill="${col}" stroke="#fff" stroke-width="10"/>`};
const qr=(x,y,w)=>{let o=`<rect x="${x}" y="${y}" width="${w}" height="${w}" fill="#fff"/>`;const c=w/7;for(let i=0;i<7;i++)for(let j=0;j<7;j++)if(((i*3+j*5+i*j)%3==0)||(i<2&&j<2)||(i>4&&j<2)||(i<2&&j>4))o+=`<rect x="${x+i*c}" y="${y+j*c}" width="${c}" height="${c}" fill="#111"/>`;return o};
const mat=(x,y,w,h)=>`<g><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="#e9d8a6"/>${Array.from({length:Math.floor(h/24)},(_,i)=>`<rect x="${x}" y="${y+i*24+6}" width="${w}" height="10" fill="${i%2?'#c08a3e':'#2e8b2e'}" opacity=".55"/>`).join('')}${Array.from({length:Math.floor(w/40)},(_,i)=>`<rect x="${x+i*40+14}" y="${y}" width="6" height="${h}" fill="#7c5a2a" opacity=".25"/>`).join('')}<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10" fill="none" stroke="#8a6a2a" stroke-width="6"/></g>`;
const cash=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><rect x="-70" y="-36" width="140" height="72" rx="10" fill="#86efac" stroke="#15803d" stroke-width="5"/><circle cx="0" cy="0" r="20" fill="none" stroke="#15803d" stroke-width="5"/>${tx(0,10,'৳',28,'#15803d',800)}</g>`;
